    rmSync(dir, { recursive: true, force: true });
  }

  console.log(
    failures.length === 0
      ? "PASS"
      : `FAIL:\n${failures.map((f) => `  - ${f}`).join("\n")}`,
  );
  return { name: c.name, failures };
